{
  "items": [
    {
      "observations": [
        {"interpretation": "«Каждая» явно задаёт всеобщность по пекарням.", "role": "literal_quantifier", "token_index": 0},
        {"interpretation": "«пекарня» соответствует сорту bakery.", "role": "entity_type", "token_index": 1},
        {"interpretation": "«снабжает» соответствует Supplies с аргументами пекарня, кофейня.", "role": "predicate", "token_index": 2},
        {"interpretation": "«хотя бы одну» явно задаёт нижнюю границу один, без требования единственности.", "role": "literal_quantifier", "token_index": 5},
        {"interpretation": "«кофейню» соответствует сорту cafe.", "role": "entity_type", "token_index": 6},
        {"interpretation": "Предлагается зависимый выбор кофейни для каждой пекарни; отрицания в тексте нет.", "role": "proposed_scope", "token_index": 0}
      ],
      "open_alternatives": [
        "Контекст мог бы выделять общую кофейню для всех пекарен; сам текст не требует общего получателя."
      ],
      "proposals": [
        {
          "added_assumptions": [],
          "binder_links": [
            {"token_index": 0, "var": "b"},
            {"token_index": 5, "var": "c"}
          ],
          "formula_json": "{\"quant\":\"forall\",\"var\":\"b\",\"sort\":\"bakery\",\"body\":{\"quant\":\"exists\",\"var\":\"c\",\"sort\":\"cafe\",\"body\":{\"pred\":\"Supplies\",\"args\":[{\"var\":\"b\"},{\"var\":\"c\"}]}}}",
          "reading": "Каждая пекарня снабжает хотя бы одну кофейню; кофейни могут различаться.",
          "token_indices": [0, 1, 2, 3, 4, 5, 6]
        }
      ],
      "source_sha256": "e46602f40eef5bd97cc4668bf1c1f370816b6537d5a2c193b26269c5fdd9a04b",
      "unsupported": []
    },
    {
      "observations": [
        {"interpretation": "«Есть» явно вводит существование кладовщика.", "role": "literal_quantifier", "token_index": 0},
        {"interpretation": "«кладовщик» соответствует сорту clerk.", "role": "entity_type", "token_index": 1},
        {"interpretation": "«который» отсылает к введённому кладовщику.", "role": "anaphora", "token_index": 2},
        {"interpretation": "«выдал» соответствует Issued с порядком аргументов кладовщик, инструмент, механик.", "role": "predicate", "token_index": 3},
        {"interpretation": "«инструмент» соответствует сорту tool; явного определителя нет.", "role": "entity_type", "token_index": 4},
        {"interpretation": "«каждому» явно задаёт всеобщность по механикам.", "role": "literal_quantifier", "token_index": 5},
        {"interpretation": "«механику» соответствует сорту mechanic.", "role": "entity_type", "token_index": 6},
        {"interpretation": "Неопределённый инструмент допускает общий или зависимый от механика выбор; отрицания нет.", "role": "proposed_scope", "token_index": 4}
      ],
      "open_alternatives": [
        "Зависимый выбор инструмента не требует, чтобы разным механикам выдавались разные инструменты.",
        "Контекстуальная определённость слова «инструмент» не установлена."
      ],
      "proposals": [
        {
          "added_assumptions": [
            "Неопределённое существительное «инструмент» интерпретируется экзистенциально в области каждого механика.",
            "Issued передаёт факт выдачи без отдельного кодирования прошедшего времени."
          ],
          "binder_links": [
            {"token_index": 0, "var": "c"},
            {"token_index": 5, "var": "m"},
            {"token_index": 4, "var": "t"}
          ],
          "formula_json": "{\"quant\":\"exists\",\"var\":\"c\",\"sort\":\"clerk\",\"body\":{\"quant\":\"forall\",\"var\":\"m\",\"sort\":\"mechanic\",\"body\":{\"quant\":\"exists\",\"var\":\"t\",\"sort\":\"tool\",\"body\":{\"pred\":\"Issued\",\"args\":[{\"var\":\"c\"},{\"var\":\"t\"},{\"var\":\"m\"}]}}}}",
          "reading": "Есть кладовщик, выдавший каждому механику некоторый инструмент, возможно разный.",
          "token_indices": [0, 1, 2, 3, 4, 5, 6]
        },
        {
          "added_assumptions": [
            "«Инструмент» получает чтение одного общего объекта для всех механиков.",
            "Issued передаёт факт выдачи без отдельного кодирования прошедшего времени."
          ],
          "binder_links": [
            {"token_index": 0, "var": "c"},
            {"token_index": 4, "var": "t"},
            {"token_index": 5, "var": "m"}
          ],
          "formula_json": "{\"quant\":\"exists\",\"var\":\"c\",\"sort\":\"clerk\",\"body\":{\"quant\":\"exists\",\"var\":\"t\",\"sort\":\"tool\",\"body\":{\"quant\":\"forall\",\"var\":\"m\",\"sort\":\"mechanic\",\"body\":{\"pred\":\"Issued\",\"args\":[{\"var\":\"c\"},{\"var\":\"t\"},{\"var\":\"m\"}]}}}}",
          "reading": "Есть кладовщик и один инструмент, который этот кладовщик выдал каждому механику.",
          "token_indices": [0, 1, 2, 3, 4, 5, 6]
        }
      ],
      "source_sha256": "aa667c18e1225ade633f30a6ff2ab0777d8300c725a30b02fe1a998c7df25dcd",
      "unsupported": []
    },
    {
      "observations": [
        {"interpretation": "«Хотя бы одну» явно означает существование без ограничения сверху.", "role": "literal_quantifier", "token_index": 2},
        {"interpretation": "«рукопись» соответствует сорту manuscript.", "role": "entity_type", "token_index": 3},
        {"interpretation": "«прочитал» соответствует Read с аргументами рецензент, рукопись.", "role": "predicate", "token_index": 4},
        {"interpretation": "«каждый» явно задаёт всеобщность по рецензентам.", "role": "literal_quantifier", "token_index": 5},
        {"interpretation": "«рецензент» соответствует сорту reviewer.", "role": "entity_type", "token_index": 6},
        {"interpretation": "Начальная позиция дополнения допускает общую рукопись, но не исключает распределительного чтения; отрицания нет.", "role": "proposed_scope", "token_index": 3}
      ],
      "open_alternatives": [
        "Порядок слов сам по себе не устанавливает единственную область действия кванторов."
      ],
      "proposals": [
        {
          "added_assumptions": [
            "Начальное дополнение интерпретируется как имеющее широкую область действия.",
            "Read передаёт факт чтения без отдельного кодирования прошедшего времени."
          ],
          "binder_links": [
            {"token_index": 2, "var": "m"},
            {"token_index": 5, "var": "r"}
          ],
          "formula_json": "{\"quant\":\"exists\",\"var\":\"m\",\"sort\":\"manuscript\",\"body\":{\"quant\":\"forall\",\"var\":\"r\",\"sort\":\"reviewer\",\"body\":{\"pred\":\"Read\",\"args\":[{\"var\":\"r\"},{\"var\":\"m\"}]}}}",
          "reading": "Есть хотя бы одна рукопись, которую прочитали все рецензенты.",
          "token_indices": [0, 1, 2, 3, 4, 5, 6]
        },
        {
          "added_assumptions": [
            "Начальное дополнение допускает узкую область действия относительно «каждый».",
            "Read передаёт факт чтения без отдельного кодирования прошедшего времени."
          ],
          "binder_links": [
            {"token_index": 5, "var": "r"},
            {"token_index": 2, "var": "m"}
          ],
          "formula_json": "{\"quant\":\"forall\",\"var\":\"r\",\"sort\":\"reviewer\",\"body\":{\"quant\":\"exists\",\"var\":\"m\",\"sort\":\"manuscript\",\"body\":{\"pred\":\"Read\",\"args\":[{\"var\":\"r\"},{\"var\":\"m\"}]}}}",
          "reading": "Каждый рецензент прочитал хотя бы одну рукопись, необязательно общую для всех.",
          "token_indices": [0, 1, 2, 3, 4, 5, 6]
        }
      ],
      "source_sha256": "308e0961c3e87065ae959b3981056834e5e12cb87138388da7541ab1f48ead0a",
      "unsupported": []
    },
    {
      "observations": [
        {"interpretation": "«Каждой» явно задаёт всеобщность по аптекам.", "role": "literal_quantifier", "token_index": 0},
        {"interpretation": "«аптеке» соответствует сорту pharmacy и обозначает получателя.", "role": "entity_type", "token_index": 1},
        {"interpretation": "«поставляют» соответствует Supplies с аргументами склад, аптека.", "role": "predicate", "token_index": 2},
        {"interpretation": "«все» явно задаёт всеобщность по складам.", "role": "literal_quantifier", "token_index": 3},
        {"interpretation": "«склады» соответствует сорту warehouse и является подлежащим.", "role": "entity_type", "token_index": 4},
        {"interpretation": "Предлагается распределительное чтение обоих кванторов; их перестановка не меняет формулу по существу. Отрицания нет.", "role": "proposed_scope", "token_index": 3}
      ],
      "open_alternatives": [
        "Совместная поставка складов как коллектива не выражается данной сигнатурой; текст не требует такого чтения.",
        "Поставляемые товары не названы и не вводятся как дополнительные аргументы."
      ],
      "proposals": [
        {
          "added_assumptions": [
            "«Все склады» понимается распределительно, а не как отдельный коллективный субъект."
          ],
          "binder_links": [
            {"token_index": 0, "var": "p"},
            {"token_index": 3, "var": "w"}
          ],
          "formula_json": "{\"quant\":\"forall\",\"var\":\"p\",\"sort\":\"pharmacy\",\"body\":{\"quant\":\"forall\",\"var\":\"w\",\"sort\":\"warehouse\",\"body\":{\"pred\":\"Supplies\",\"args\":[{\"var\":\"w\"},{\"var\":\"p\"}]}}}",
          "reading": "Каждый склад поставляет каждой аптеке.",
          "token_indices": [0, 1, 2, 3, 4]
        }
      ],
      "source_sha256": "b3aacd74c4a6eda094e2aee94d2cb451a68a8d39e89052eb22c4db35ee7e1405",
      "unsupported": []
    },
    {
      "observations": [
        {"interpretation": "«Кто-нибудь» вводит неопределённого участника; в предлагаемом утвердительном чтении — существующего курьера.", "role": "literal_quantifier", "token_index": 0},
        {"interpretation": "«из курьеров» ограничивает участника сортом courier.", "role": "entity_type", "token_index": 2},
        {"interpretation": "«доставил» соответствует Delivered с аргументами курьер, посылка, адресат.", "role": "predicate", "token_index": 3},
        {"interpretation": "«посылку» соответствует сорту parcel; явного определителя нет.", "role": "entity_type", "token_index": 4},
        {"interpretation": "«всем» явно задаёт всеобщность по адресатам.", "role": "literal_quantifier", "token_index": 5},
        {"interpretation": "«адресатам» соответствует сорту recipient.", "role": "entity_type", "token_index": 6},
        {"interpretation": "Предлагаются общий и зависимый выбор посылки при одном курьере; отрицания нет.", "role": "proposed_scope", "token_index": 4}
      ],
      "open_alternatives": [
        "Контекстуальная определённость посылки не установлена.",
        "Зависимый выбор посылки не требует разных посылок для разных адресатов."
      ],
      "proposals": [
        {
          "added_assumptions": [
            "Предложение понимается как утверждение о существующем курьере.",
            "«Посылку» обозначает один общий объект для всех адресатов.",
            "Delivered передаёт факт доставки без отдельного кодирования прошедшего времени."
          ],
          "binder_links": [
            {"token_index": 0, "var": "c"},
            {"token_index": 4, "var": "p"},
            {"token_index": 5, "var": "r"}
          ],
          "formula_json": "{\"quant\":\"exists\",\"var\":\"c\",\"sort\":\"courier\",\"body\":{\"quant\":\"exists\",\"var\":\"p\",\"sort\":\"parcel\",\"body\":{\"quant\":\"forall\",\"var\":\"r\",\"sort\":\"recipient\",\"body\":{\"pred\":\"Delivered\",\"args\":[{\"var\":\"c\"},{\"var\":\"p\"},{\"var\":\"r\"}]}}}}",
          "reading": "Некоторый курьер доставил одну общую посылку всем адресатам.",
          "token_indices": [0, 1, 2, 3, 4, 5, 6]
        },
        {
          "added_assumptions": [
            "Предложение понимается как утверждение о существующем курьере.",
            "Неопределённая посылка выбирается в области каждого адресата.",
            "Delivered передаёт факт доставки без отдельного кодирования прошедшего времени."
          ],
          "binder_links": [
            {"token_index": 0, "var": "c"},
            {"token_index": 5, "var": "r"},
            {"token_index": 4, "var": "p"}
          ],
          "formula_json": "{\"quant\":\"exists\",\"var\":\"c\",\"sort\":\"courier\",\"body\":{\"quant\":\"forall\",\"var\":\"r\",\"sort\":\"recipient\",\"body\":{\"quant\":\"exists\",\"var\":\"p\",\"sort\":\"parcel\",\"body\":{\"pred\":\"Delivered\",\"args\":[{\"var\":\"c\"},{\"var\":\"p\"},{\"var\":\"r\"}]}}}}",
          "reading": "Некоторый курьер доставил каждому адресату некоторую посылку, необязательно общую для всех.",
          "token_indices": [0, 1, 2, 3, 4, 5, 6]
        }
      ],
      "source_sha256": "d263af2e34cffa8a74743010ad8de995ab8e33787543879d97aa8120b314299b",
      "unsupported": []
    },
    {
      "observations": [
        {"interpretation": "«Есть» явно утверждает существование пилота.", "role": "literal_quantifier", "token_index": 0},
        {"interpretation": "«пилот» соответствует сорту pilot.", "role": "entity_type", "token_index": 1},
        {"interpretation": "«осмотревший» соответствует Inspected с аргументами пилот, ангар.", "role": "predicate", "token_index": 2},
        {"interpretation": "Неявный субъект причастия — введённый пилот.", "role": "anaphora_ellipsis", "token_index": 2},
        {"interpretation": "«каждый» явно задаёт всеобщность по ангарам.", "role": "literal_quantifier", "token_index": 3},
        {"interpretation": "«ангар» соответствует сорту hangar.", "role": "entity_type", "token_index": 4},
        {"interpretation": "Причастная конструкция характеризует одного существующего пилота осмотром всех ангаров; отрицания нет.", "role": "proposed_scope", "token_index": 2}
      ],
      "open_alternatives": [
        "Область контекстуально релевантных ангаров не уточняется.",
        "Чтение с разными пилотами для разных ангаров не передаёт явное утверждение о пилоте, осмотревшем каждый ангар."
      ],
      "proposals": [
        {
          "added_assumptions": [
            "Inspected передаёт факт осмотра без отдельного кодирования прошедшего времени."
          ],
          "binder_links": [
            {"token_index": 0, "var": "p"},
            {"token_index": 3, "var": "h"}
          ],
          "formula_json": "{\"quant\":\"exists\",\"var\":\"p\",\"sort\":\"pilot\",\"body\":{\"quant\":\"forall\",\"var\":\"h\",\"sort\":\"hangar\",\"body\":{\"pred\":\"Inspected\",\"args\":[{\"var\":\"p\"},{\"var\":\"h\"}]}}}",
          "reading": "Существует пилот, осмотревший все ангары.",
          "token_indices": [0, 1, 2, 3, 4]
        }
      ],
      "source_sha256": "b08bce3bca1c534757a4c2d851f09bd453fdce8c07637b7b4a2a7b484636f3fd",
      "unsupported": []
    }
  ]
}

